INSERT INTO parks (name, lat, lon, region) SELECT 'Ocean Park', 22.2467, 114.1757, 'Hong Kong' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Ocean Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Arctic Blast', 'Ocean Park', 'Steel', 'MACK Rides', 'MACK Powered Coaster', NULL, NULL, NULL, 0, NULL, 2012, '2012-07-13', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Arctic Blast' AND park = 'Ocean Park');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Arctic Blast' AND c.park = 'Ocean Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
